
import re

file_path = 'lib/visualLab/data/hungaryPoi.ts'

with open(file_path, 'r', encoding='utf-8') as f:
    content = f.read()

def update_poi(content, poi_id, desc_de, facts_de):
    pattern = re.compile(rf'(\{{\s+id:\s*"{poi_id}",[\s\S]*?\n\s+\}})', re.MULTILINE)
    match = pattern.search(content)
    if not match: return content
    block = match.group(1)
    if 'descriptionAdvanced:' in block:
        de_match = re.search(r'descriptionAdvanced:\s*\{[^}]*"de":\s*"([^"]*)"', block)
        if de_match and not de_match.group(1):
            block = re.sub(r'(descriptionAdvanced:\s*\{[^}]*"de":\s*")([^"]*)(")', rf'\1{desc_de}\3', block)
    else:
        desc_pattern = re.compile(r'(description:\s*\{[\s\S]*?\s+\},)', re.MULTILINE)
        new_desc_adv = f'\n    descriptionAdvanced: {{ "de": "{desc_de}", "hu": "", "ro": "", "en": "" }},'
        block = desc_pattern.sub(rf'\1{new_desc_adv}', block)
    if 'factsAdvanced:' not in block:
        facts_str = '", "'.join(facts_de)
        new_facts_adv = f'\n    factsAdvanced: {{\n      "de": ["{facts_str}"],\n      "hu": [],\n      "ro": [],\n      "en": []\n    }},'
        if 'facts:' in block:
            facts_block_pattern = re.compile(r'(facts:\s*\{[\s\S]*?\s+\},)', re.MULTILINE)
            block = facts_block_pattern.sub(rf'\1{new_facts_adv}', block)
        else:
            block = re.sub(r'(\n\s+\})$', rf'{new_facts_adv}\1', block)
    return content.replace(match.group(1), block)

